  if (info === null || map.value === null) {
    rectangleSelectionActive.value = false;
    return;
  }
  if (rectangleIsDegenerate(info)) {
    // make it a point selection instead
    // TODO: only implement when we have a solution to only do this on a double-click
    // pointInfo.value = {
    //   x: info.xmin,
    //   y: info.ymin
    // };
    rectangleSelectionActive.value = false;
    return;
  }

  const newRegion = createRegion(info, "rectangle");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  store.addRegion(newRegion as any);
  // Hand the new region's card the focus. Drawing a region left focus on the
  // map, a long way in the tab order from the regions panel, with nothing to
  // say a region had been made; DatasetControls picks this up.
  focusCardId.value = newRegion.id;
  rectangleSelectionActive.value = false;
  
  // do not permit editing a region on a selection
  // handleSelectionRegionEdit(info);
  

});

// Add watcher for point selection
watch(pointInfo, (info: PointSelectionInfo | null) => {
  if (info === null || map.value === null) {
    pointSelectionActive.value = false;
    return;
  }
  const newRegion = createRegion(info, "point");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  store.addRegion(newRegion as any);
  focusCardId.value = newRegion.id;
  pointSelectionActive.value = false;
});

// when we move the selection - replace that one with a region  with a new id
watch(moveInfo, (info: RectangleSelectionInfo | null) => {
  const region = regionBeingMoved.value;
  if (info !== null && region !== null && region.geometryType === "rectangle") {
    const moved: UnifiedRegionType = { ...region, id: v4(), geometryInfo: info };
    const currentIndex = regions.value.indexOf(region);
    if (currentIndex !== -1 ) {
      regions.value.splice(currentIndex, 1, moved);
    }
    focusCardId.value = moved.id;
  }
  moveSelectionActive.value = false;
});

// Whether the move finished, or was cancelled with Escape or by starting
// another selection
watch(moveSelectionActive, (active: boolean) => {
  if (!active) {
    regionToMove.value = null;
  }
});

